-- Generated from the development database.
-- Scope: role definitions, permission definitions, and effective role-permission mappings.
-- Per-user assignments (user_roles and user_permissions) are intentionally excluded.
-- Permission definitions are matched by permission_key, not development IDs.
-- One local-only super-admin login is upserted by email without copying any user ID.
-- Development contained duplicate role_permissions history; this export keeps one
-- effective row per role/permission-key pair using MAX(is_active).

SET NAMES utf8mb4;
SET @previous_sql_safe_updates = @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

ON DUPLICATE KEY UPDATE
  user_role = VALUES(user_role),
  description = VALUES(description),
  is_internal_member = VALUES(is_internal_member),
  is_active = VALUES(is_active),
  created_at = VALUES(created_at),
  updated_at = VALUES(updated_at);

ON DUPLICATE KEY UPDATE
  role_key = VALUES(role_key),
  module_key = VALUES(module_key),
  action_key = VALUES(action_key),
  permission_key = VALUES(permission_key),
  is_active = VALUES(is_active);

-- Rebuild mappings to remove local drift and avoid importing development duplicates.
DELETE FROM role_permissions;

DROP TEMPORARY TABLE IF EXISTS sync_role_permission_keys;
CREATE TEMPORARY TABLE sync_role_permission_keys (
  role_id INT NOT NULL,
  permission_key VARCHAR(150) NOT NULL,
  is_active TINYINT(1) NOT NULL,
  PRIMARY KEY (role_id, permission_key)
);


SELECT source.role_id, permission.permission_id, source.is_active
FROM sync_role_permission_keys source
JOIN permissions permission
  ON permission.permission_key = source.permission_key;

DROP TEMPORARY TABLE sync_role_permission_keys;

-- This account receives a new local auto-increment ID if it does not already exist.
-- It uses a known local-only password and never copies a development user ID.
ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  password_hash = VALUES(password_hash),
  auth_provider = VALUES(auth_provider),
  email_verified = VALUES(email_verified),
  is_active = VALUES(is_active),
  user_type = VALUES(user_type),
  role = VALUES(role),
  permissions_version = permissions_version + 1;

-- Remove definitions that do not exist in development. These deletes intentionally
-- fail and roll back if a stale definition is still referenced by a local FK row.
DELETE FROM permissions
WHERE permission_key NOT IN ('admin_dashboard.delete', 'admin_dashboard.edit', 'admin_dashboard.create', 'admin_dashboard.view', 'admin_shoots.delete', 'admin_shoots.edit', 'admin_shoots.create', 'admin_shoots.view', 'admin_file_manager.delete', 'admin_file_manager.edit', 'admin_file_manager.create', 'admin_file_manager.view', 'admin_meetings.delete', 'admin_meetings.edit', 'admin_meetings.create', 'admin_meetings.view', 'admin_messages.delete', 'admin_messages.edit', 'admin_messages.create', 'admin_messages.view', 'admin_availability.delete', 'admin_availability.edit', 'admin_availability.create', 'admin_availability.view', 'admin_sales_representative.delete', 'admin_sales_representative.edit', 'admin_sales_representative.create', 'admin_sales_representative.view', 'admin_finances.delete', 'admin_finances.edit', 'admin_finances.create', 'admin_finances.view', 'admin_users.delete', 'admin_users.edit', 'admin_users.create', 'admin_users.view', 'admin_quotes.delete', 'admin_quotes.edit', 'admin_quotes.create', 'admin_quotes.view', 'admin_invoices.delete', 'admin_invoices.edit', 'admin_invoices.create', 'admin_invoices.view', 'creative_partner_dashboard.delete', 'creative_partner_dashboard.edit', 'creative_partner_dashboard.create', 'creative_partner_dashboard.view', 'creative_partner_request_shoots.delete', 'creative_partner_request_shoots.edit', 'creative_partner_request_shoots.create', 'creative_partner_request_shoots.view', 'creative_partner_file_manager.delete', 'creative_partner_file_manager.edit', 'creative_partner_file_manager.create', 'creative_partner_file_manager.view', 'creative_partner_meetings.delete', 'creative_partner_meetings.edit', 'creative_partner_meetings.create', 'creative_partner_meetings.view', 'creative_partner_messages.delete', 'creative_partner_messages.edit', 'creative_partner_messages.create', 'creative_partner_messages.view', 'creative_partner_affiliate.delete', 'creative_partner_affiliate.edit', 'creative_partner_affiliate.create', 'creat