WHERE user_type_id NOT IN (1, 2, 3, 5, 6, 7, 8, 9, 10, 11, 12);

COMMIT;
SET SQL_SAFE_UPDATES = @previous_sql_safe_updates;

-- Expected results: 11 roles, 272 permissions,
-- 804 effective mappings.
SELECT 'user_type' AS table_name, COUNT(*) AS row_count FROM user_type
UNION ALL
SELECT 'permissions', COUNT(*) FROM permissions
UNION ALL
SELECT 'role_permissions', COUNT(*) FROM role_permissions;
